const dbp=new Promise((resolve,reject)=>{const req=indexedDB.open('dibiser_almacen_v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('movements',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
async function allLocal(){const db=await dbp;return new Promise((res,rej)=>{let r=db.transaction('movements').objectStore('movements').getAll();r.onsuccess=()=>res(r.result.sort((a,b)=>b.iso.localeCompare(a.iso)));r.onerror=()=>rej(r.error)})}
async function putLocal(r){const db=await dbp;return new Promise((res,rej)=>{let t=db.transaction('movements','readwrite');t.objectStore('movements').put(r);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function all(){
  const local=await allLocal();
  if(!window.DibiserCloud?.connected())return local;
  let remote=[];
  try{remote=await window.DibiserCloud.all();}
  catch(error){
    // Sin internet jamás se oculta el historial guardado en el teléfono.
    if(local.length){$('recoveryStatus').textContent='Mostrando '+local.length+' movimientos locales. La nube no respondió: '+error.message;return local;}
    throw error;
  }
  const merged=new Map(local.map(r=>[r.id,r]));
  for(const r of remote)merged.set(r.id,r);
  return [...merged.values()].sort((x,y)=>String(y.iso).localeCompare(String(x.iso)));
}
async function put(r){
 if(window.DibiserCloud?.connected()){
   // El servidor asigna el correlativo definitivo incluso con varios celulares simultáneos.
   const result=await window.DibiserCloud.save(r,r.guiaManual?r.guia:null,false);
   Object.assign(r,result);delete r.guiaManual;
   await putLocal(r);return result;
 }
 if(window.DibiserCloud?.configured())throw Error('No se pudo guardar: inicia sesión en la base central. Tus registros no se enviaron.');
 delete r.guiaManual;return putLocal(r);
}
function nowLocal(){return new Date().toLocaleString('es-PE',{timeZone:'America/Lima'})}
function dateKey(iso){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(iso));const part=t=>parts.find(p=>p.type===t).value;return `${part('year')}-${part('month')}-${part('day')}`}
function today(){return dateKey(new Date().toISOString())}
function show(tab){
 if(!$(tab))return;
 AppMotion.switchPage($(tab));
 document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x.dataset.tab===tab);x.setAttribute('aria-current',x.dataset.tab===tab?'page':'false')});
 if(tab==='report')AppMotion.task($(tab),renderReport).catch(AppMotion.error);
 if(tab==='history')AppMotion.task($(tab),refreshSharedHistory).catch(AppMotion.error);
 if(tab==='catalogs')renderCatalog();
}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>show(b.dataset.tab));
$('reportDate').value=today();setInterval(()=>{$('timestamp').value=nowLocal()},1000);$('timestamp').value=nowLocal();
function addCatalog(k,v){v=v.trim();if(!v)return false;if(catalogs[k].some(x=>x.toLocaleLowerCase('es')===v.toLocaleLowerCase('es')))return true;catalogs[k].push(v);catalogs[k].sort((a,b)=>a.localeCompare(b,'es'));saveCats();if(window.DibiserCloud?.connected())window.DibiserCloud.saveCatalog(k,v).catch(e=>AppMotion.notify('Catálogo local pendiente de sincronización: '+e.message));return true}
for(const root of document.querySelectorAll('[data-combo]')){
 const k=root.dataset.combo,inp=root.querySelector('input'),menu=root.querySelector('.menu');
 menu.id='options-'+k;menu.setAttribute('role','group');menu.setAttribute('aria-label','Opciones de '+k);
 inp.setAttribute('aria-controls',menu.id);inp.setAttribute('aria-expanded','false');
 function close(){AppMotion.hide(menu);inp.setAttribute('aria-expanded','false')}
 function render(){
  const q=inp.value.trim().toLocaleLowerCase('es');const matches=catalogs[k].filter(x=>x.toLocaleLowerCase('es').includes(q)).slice(0,75);
  menu.replaceChildren();
  for(const x of matches){const b=document.createElement('button');b.type='button';b.textContent=x;b.onclick=()=>{inp.value=x;inp.dispatchEvent(new Event('change',{bubbles:true}));close();inp.focus({preventScroll:true});close()};menu.append(b)}
  if(!matches.length)menu.innerHTML='<div class="muted" style="padding:10px">Sin coincidencias. Usa ＋ para agregar.</div>';
  AppMotion.show(menu,'menu');inp.setAttribute('aria-expanded','true');
 }
 inp.oninput=render;inp.onfocus=render;
 root.querySelector('.add').onclick=()=>{if(!inp.value.trim()){AppMotion.notify('Escribe primero el nombre o código.');inp.focus();return}if(addCatalog(k,inp.value)){close();AppMotion.notify('Agregado al catálogo: '+inp.value)}};
 root.addEventListener('focusout',()=>setTimeout(()=>{if(!root.contains(document.activeElement))close()},0));
 root.addEventListener('keydown',e=>{const buttons=[...menu.querySelectorAll('button')];if(e.key==='Escape'){close();inp.focus({preventScroll:true});close()}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(menu.classList.contains('hidden'))render();const options=[...menu.querySelectorAll('button')];let i=options.indexOf(document.activeElement);i=(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[i]?.focus()} });
 document.addEventListener('pointerdown',e=>{if(!root.contains(e.target))close()});
}
// Correlativo de control interno, independiente de la numeración oficial SUNAT.
// Se calcula con los registros existentes y los números generados localmente.
async function siguienteGuiaInterna(){
  if(window.DibiserCloud?.connected())return window.DibiserCloud.preview();
  const prev=[...(catalogs.guias||[]),...(await all()).map(r=>r.guia||'')];
  let max=0;
  for(const value of prev){const match=/^DIB-INT-(\d+)$/i.exec(String(value).trim());if(match)max=Math.max(max,Number(match[1]));}
  return 'DIB-INT-'+String(max+1).padStart(6,'0');
}
let guiaModificada=false;
async function mostrarGuiaAutomatica(){
  if(guiaModificada)return;
  const input=$('guias');input.readOnly=true;input.setAttribute('aria-readonly','true');
  $('modificarGuia').textContent='Modificar';
  try{input.value=await siguienteGuiaInterna();}
  catch(err){input.value='';console.warn('Error al consultar correlativo de guía:',err)}
}
$('modificarGuia').onclick=async()=>{
  if(!guiaModificada){
    guiaModificada=true;$('guias').readOnly=false;$('guias').setAttribute('aria-readonly','false');
    $('modificarGuia').textContent='Automático';
    $('guias').focus();$('guias').select();
  }else{
    guiaModificada=false;await mostrarGuiaAutomatica();
  }
};
mostrarGuiaAutomatica();
const MAX_PHOTOS=1;
function actualizarTransporte(){
  const entrada=$('tipo').value==='Entrada';
  const opcionServicio=$('opcionServicio');
  opcionServicio.disabled=entrada;
  // En las entradas no se permite la configuración de salida por trabajo.
  if(entrada&&$('configTransporte').value==='Trabajo / servicio')$('configTransporte').value='Unidad sola';
  const cfg=$('configTransporte').value;
  const carreta=cfg==='Con carreta',cama=cfg==='Con cama baja',servicio=cfg==='Trabajo / servicio';
  $('campoCliente').classList.toggle('hidden',servicio);
  $('clientes').required=!servicio;
  if(servicio)$('clientes').value='';
  $('campoMaterial').classList.toggle('hidden',cama||servicio);
  $('campoMaquinariaTransportada').classList.toggle('hidden',!cama);
  $('campoCarreta').classList.toggle('hidden',!carreta);
  $('campoCamaBaja').classList.toggle('hidden',!cama);
  $('campoCantidad').classList.toggle('hidden',servicio);
  $('campoUnidad').classList.toggle('hidden',servicio);
  $('materiales').required=!cama&&!servicio;
  $('maquinarias').required=cama;
  $('carretas').required=carreta;
  $('camasBajas').required=cama;
  $('cantidad').required=!servicio;
  if(cama){$('materiales').value='';$('unidad').value='Unidad';$('cantidad').value='1';$('cantidad').readOnly=false;}
  else if(servicio){$('materiales').value='';$('cantidad').value='';$('unidad').value='Unidad';$('cantidad').readOnly=false;}
  if(!carreta)$('carretas').value='';
  if(!cama){$('camasBajas').value='';$('maquinarias').value='';}
  actualizarTrabajo();
}
function actualizarTrabajo(){
  const activo=$('tipo').value==='Salida'&&$('configTransporte').value==='Trabajo / servicio';
  $('campoTrabajo').classList.toggle('hidden',!activo);
  $('trabajos').required=activo;
  if(!activo)$('trabajos').value='';
}
$('tipo').addEventListener('change',actualizarTransporte);
$('configTransporte').addEventListener('change',actualizarTransporte);

actualizarTransporte();

let photoData=[],photoProcessing=false;
function compress(file){return new Promise((res,rej)=>{const reader=new FileReader();reader.onerror=()=>rej(reader.error);reader.onload=()=>{let im=new Image();im.onload=()=>{let scale=Math.min(1,1300/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);res(canvas.toDataURL('image/jpeg',.68))};im.onerror=()=>rej(Error('Imagen inválida'));im.src=reader.result};reader.readAsDataURL(file)})}
// Cámara integrada (getUserMedia); captura nativa como alternativa móvil.
let cameraStream=null,cameraFacing='environment',cameraRequest=0;
function renderPhotoPreview(){
 $('photoCount').textContent=photoData.length+' de 1 foto';
 $('cameraCounter').textContent=photoData.length+' de 1 foto';
 $('preview').innerHTML=photoData.map((src,i)=>`<div class="photo-evidence"><img src="${src}" alt="Evidencia del movimiento"><button type="button" data-photo="${i}" aria-label="Quitar fotografía">×</button></div>`).join('');
 $('preview').querySelectorAll('[data-photo]').forEach(b=>b.onclick=async()=>{b.disabled=true;await AppMotion.remove(b.parentElement);photoData=[];renderPhotoPreview();$('openCamera').focus()});
 $('capturePhoto').disabled=photoData.length>=MAX_PHOTOS||!cameraStream||photoProcessing;
 $('openCamera').disabled=photoData.length>=MAX_PHOTOS||photoProcessing;
 $('cameraNative').disabled=photoData.length>=MAX_PHOTOS||photoProcessing;
 AppMotion.reveal($('preview'));
}
function stopCamera(){cameraRequest++;if(cameraStream){cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null}$('cameraVideo').srcObject=null}
function closeCamera(){stopCamera();AppMotion.hide($('cameraModal'));document.querySelector('main').inert=false;document.querySelector('header').inert=false;document.body.classList.remove('camera-open');const focus=$('openCamera').disabled?$('preview').querySelector('button'):$('openCamera');focus?.focus({preventScroll:true})}
async function startCamera(){
 if(photoData.length>=MAX_PHOTOS||photoProcessing)return AppMotion.notify('Ya tienes una fotografía. Quítala para tomar otra.');
 AppMotion.show($('cameraModal'),'modal');document.querySelector('main').inert=true;document.querySelector('header').inert=true;document.body.classList.add('camera-open');$('closeCamera').focus();
 $('cameraStatus').textContent='Solicitando permiso para usar la cámara…';
 stopCamera();const request=cameraRequest;$('capturePhoto').disabled=true;
 if(!navigator.mediaDevices?.getUserMedia){$('cameraStatus').textContent='Usa «Abrir cámara del celular» o publica la aplicación en HTTPS.';return}
 const finish=AppMotion.busy($('cameraStatus'));
 try{
  const stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:cameraFacing},width:{ideal:1280},height:{ideal:960}}});
  if(request!==cameraRequest){stream.getTracks().forEach(track=>track.stop());return}
  cameraStream=stream;const video=$('cameraVideo');video.srcObject=stream;await video.play();
  if(request!==cameraRequest)return;
  $('capturePhoto').disabled=false;$('cameraStatus').textContent='Cámara lista. Enfoca la evidencia y pulsa «Capturar foto».';
 }catch(err){if(request===cameraRequest)$('cameraStatus').textContent='No se pudo abrir la cámara ('+err.name+'). Revisa los permisos o usa «Abrir cámara del celular».'}
 finally{finish()}
}
$('openCamera').onclick=startCamera;
$('closeCamera').onclick=closeCamera;
$('cameraModal').addEventListener('click',e=>{if(e.target===$('cameraModal'))closeCamera()});
$('switchCamera').onclick=()=>{cameraFacing=cameraFacing==='environment'?'user':'environment';startCamera()};
$('cameraNative').onclick=()=>{$('cameraFallback').click()};
$('cameraFallback').onchange=async e=>{
 const f=e.target.files?.[0];if(!f)return;
 if(photoData.length>=MAX_PHOTOS||photoProcessing){AppMotion.notify('Solo se permite una fotografía. Quita la actual para cambiarla.');e.target.value='';return}
 photoProcessing=true;renderPhotoPreview();const finish=AppMotion.busy($('photoCount'));
 try{photoData=[await compress(f)];closeCamera();AppMotion.notify('Fotografía lista para guardar con el movimiento.')}
 catch(err){AppMotion.notify('No se pudo procesar la foto: '+err.message)}
 finally{photoProcessing=false;renderPhotoPreview();finish();e.target.value=''}
};
$('capturePhoto').onclick=()=>{
 if(photoData.length>=MAX_PHOTOS||photoProcessing)return;
 const video=$('cameraVideo');if(!cameraStream||!video.videoWidth)return;
 const scale=Math.min(1,1300/Math.max(video.videoWidth,video.videoHeight)),canvas=document.createElement('canvas');
 canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);
 photoData=[canvas.toDataURL('image/jpeg',.68)];renderPhotoPreview();closeCamera();AppMotion.notify('Fotografía lista para guardar con el movimiento.');
};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&cameraStream)closeCamera()});
window.addEventListener('pagehide',stopCamera);

$('movementForm').onsubmit=async e=>{e.preventDefault();if(photoProcessing)return AppMotion.notify('Espera a que termine de procesarse la fotografía.');const submit=$('movementForm').querySelector('[type=submit]');if(submit.disabled)return;let fields=['conductores','placas','responsables'];if($('configTransporte').value!=='Trabajo / servicio')fields.push('clientes');if($('configTransporte').value==='Trabajo / servicio'&&$('tipo').value==='Salida')fields.push('trabajos');if($('configTransporte').value==='Con cama baja')fields.push('maquinarias');else if($('configTransporte').value!=='Trabajo / servicio')fields.push('materiales');if($('configTransporte').value==='Con carreta')fields.push('carretas');if($('configTransporte').value==='Con cama baja')fields.push('camasBajas');for(let k of fields){let v=$(k).value.trim();if(!catalogs[k].some(x=>x.toLocaleLowerCase('es')===v.toLocaleLowerCase('es'))){alert('Selecciona un elemento de '+k+' o agrégalo con el botón ＋.');$(k).focus();return}}const esServicio=$('configTransporte').value==='Trabajo / servicio';if(esServicio&&$('tipo').value!=='Salida')return alert('Trabajo / servicio solo puede registrarse como salida.');let qty=esServicio?null:Number($('cantidad').value);if(!esServicio&&(!Number.isFinite(qty)||qty<0||$('cantidad').value.trim()===''))return alert('Cantidad inválida');if($('autorizacion').value==='Pendiente'&&!confirm('El movimiento está pendiente de autorización. ¿Guardar de todos modos?'))return;let iso=new Date().toISOString(),r={id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),iso,tipo:$('tipo').value,cliente:esServicio?'':$('clientes').value,conductor:$('conductores').value,placa:$('placas').value,configTransporte:$('configTransporte').value,carreta:$('configTransporte').value==='Con carreta'?$('carretas').value:'',camaBaja:$('configTransporte').value==='Con cama baja'?$('camasBajas').value:'',material:['Con cama baja','Trabajo / servicio'].includes($('configTransporte').value)?'':$('materiales').value,maquinariaTransportada:$('configTransporte').value==='Con cama baja'?$('maquinarias').value:'',trabajo:$('configTransporte').value==='Trabajo / servicio'&&$('tipo').value==='Salida'?$('trabajos').value.trim():'',cantidad:qty,unidad:esServicio?'':$('unidad').value,guia:guiaModificada?$('guias').value.trim():'',guiaManual:guiaModificada&&!!$('guias').value.trim(),autorizacion:$('autorizacion').value,observaciones:$('observaciones').value,responsable:$('responsables').value,fotos:photoData.slice(0,MAX_PHOTOS)};submit.disabled=true;const finish=AppMotion.busy(submit);try{if(!window.DibiserCloud?.connected()&&(!guiaModificada||!r.guia))r.guia=await siguienteGuiaInterna();await put(r);addCatalog('guias',r.guia);guiaModificada=false;$('movementForm').reset();await mostrarGuiaAutomatica();$('responsables').value='LUIS FELIPE ABAD QUINDE';actualizarTransporte();actualizarTrabajo();photoData=[];renderPhotoPreview();$('msg').textContent=' ✓ Guardado: '+r.id;AppMotion.notify('Movimiento guardado correctamente.');$('timestamp').value=nowLocal()}catch(err){alert('No se pudo guardar. Verifica el espacio del navegador: '+err.message)}finally{finish();submit.disabled=false}};
function rowsFor(r){return `<tr><td>${esc(new Date(r.iso).toLocaleTimeString('es-PE',{timeZone:'America/Lima',hour:'2-digit',minute:'2-digit'}))}</td><td>${esc(r.placa)}${r.carreta?'<br>Carreta: '+esc(r.carreta):''}${r.camaBaja?'<br>Cama baja: '+esc(r.camaBaja):''}</td><td>${esc(r.tipo)}</td><td>${esc(r.cliente)}</td><td>${esc(r.conductor)}</td><td>${esc(r.maquinariaTransportada?'Maquinaria: '+r.maquinariaTransportada:(r.trabajo?'Servicio: '+r.trabajo:r.material))}</td><td>${r.configTransporte==='Trabajo / servicio'?'—':esc(r.cantidad)+' '+esc(r.unidad)}</td><td>${esc(r.guia)}</td></tr>`}
async function renderReport(){let date=$('reportDate').value,rr=(await all()).filter(r=>dateKey(r.iso)===date);$('printedDate').textContent=date.split('-').reverse().join('/');$('total').textContent=rr.length;$('entries').textContent=rr.filter(r=>r.tipo==='Entrada').length;$('exits').textContent=rr.filter(r=>r.tipo==='Salida').length;$('volume').textContent=rr.filter(r=>r.unidad==='m³').reduce((s,r)=>s+(Number(r.cantidad)||0),0).toLocaleString('es-PE');$('reportRows').innerHTML=rr.map(rowsFor).join('')||'<tr><td colspan="8">Sin movimientos para esta fecha</td></tr>';let sums={};for(let r of rr){let concept=r.maquinariaTransportada?'Maquinaria: '+r.maquinariaTransportada:(r.trabajo?'Servicio: '+r.trabajo:(r.material||'Sin material'));let k=r.tipo+' · '+concept+(r.configTransporte==='Trabajo / servicio'?'':' ('+r.unidad+')');sums[k]=(sums[k]||0)+(r.configTransporte==='Trabajo / servicio'?1:Number(r.cantidad||0))}$('totalsByMaterial').innerHTML=Object.entries(sums).map(([k,v])=>`<div>${esc(k)}: <b>${esc(v)}</b></div>`).join('')||'<p class="muted">Sin materiales</p>';$('reportPhotos').innerHTML=rr.filter(r=>r.fotos?.length).map(r=>`<div style="break-inside:avoid;margin:12px 0"><b>${esc(r.id)} · ${esc(r.placa)} · ${esc(r.cliente)}</b><div class="photo">${r.fotos.map(s=>`<img src="${s}" alt="Evidencia">`).join('')}</div></div>`).join('')||'<p class="muted">Sin fotografías</p>'}
$('reportDate').onchange=()=>AppMotion.task($('report'),renderReport).catch(AppMotion.error);
function download(name,blob){let a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
$('excel').onclick=async()=>{const button=$('excel'),date=$('reportDate').value;if(!date)return AppMotion.notify('Selecciona una fecha para exportar.');if(button.disabled)return;button.disabled=true;const label=button.textContent;button.textContent='Preparando Excel…';try{const rows=(await all()).filter(r=>dateKey(r.iso)===date);if(!window.DibiserExcel?.build)throw Error('Exportador Excel no disponible. Abre la aplicación con conexión y vuelve a intentar.');const file=window.DibiserExcel.build(rows,date);download('DIBISER_movimientos_'+date+'.xlsx',file);AppMotion.notify('Libro Excel descargado con movimientos y resumen.')}catch(err){AppMotion.notify('No se pudo exportar Excel: '+err.message)}finally{button.disabled=false;button.textContent=label}};
async function renderHistory(){
 const rrAll=await all();
 const q=$('search').value.trim().toLocaleLowerCase('es');
 const f=$('filter').value,from=$('from').value,to=$('to').value;
 const rr=rrAll.filter(r=>{
  if((f!=='Todos'&&r.tipo!==f)|| (from&&dateKey(r.iso)<from)||(to&&dateKey(r.iso)>to))return false;
  return [r.id,r.guia,r.placa,r.carreta,r.camaBaja,r.maquinariaTransportada,r.trabajo,r.cliente,r.conductor,r.material].some(v=>String(v??'').toLocaleLowerCase('es').includes(q));
 });
 $('historyRows').innerHTML=rr.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(new Date(r.iso).toLocaleString('es-PE'))}</td><td>${esc(r.tipo)}</td><td>${esc(r.placa)}</td><td>${esc(r.cliente)}</td><td>${esc(r.conductor)}</td><td>${esc(r.maquinariaTransportada?'Maquinaria: '+r.maquinariaTransportada:(r.trabajo?'Servicio: '+r.trabajo:r.material))}</td><td>${r.configTransporte==='Trabajo / servicio'?'—':esc(r.cantidad)+' '+esc(r.unidad)}</td><td><button class="view" data-id="${esc(r.id)}">Ver</button></td></tr>`).join('')||'<tr><td colspan="9">No se encontraron movimientos con los filtros actuales.</td></tr>';
 document.querySelectorAll('.view').forEach(b=>b.onclick=()=>detail(rr.find(r=>r.id===b.dataset.id)));
 $('historySyncStatus').textContent='Mostrando '+rr.length+' de '+rrAll.length+' movimientos. '+($('historySyncStatus').dataset.cloudInfo||'');
}
async function refreshSharedHistory(){
 const b=$('historyReload');if(b.disabled)return;b.disabled=true;
 $('historySyncStatus').textContent='Consultando los movimientos guardados por todos los celulares...';
 try{
  const local=await allLocal();
  if(!cloud.status().authorized){
   await renderHistory();
   $('historySyncStatus').dataset.cloudInfo='';
   $('historySyncStatus').textContent='Solo este celular: '+local.length+' movimientos. Pega el enlace privado en Historial central DIBISER para consultar la base compartida.';
   return;
  }
  const remote=await cloud.all(true);
  const pending=local.filter(x=>x?.id&&!remote.some(y=>y.id===x.id)).length;
  $('historySyncStatus').dataset.cloudInfo='Base central: '+remote.length+' movimientos; este celular: '+local.length+' locales'+(pending?', pendientes por sincronizar: '+pending:'')+'.';
  await renderHistory();
  if(pending) $('recoveryStatus').textContent='Hay '+pending+' registros locales de este celular pendientes de subir a la nube. Usa Recuperar y sincronizar ahora.';
 }catch(e){
  await renderHistory();
  $('historySyncStatus').textContent='No se pudo consultar la base central: '+e.message+'. Se conservaron los movimientos locales.';
 }finally{b.disabled=false;}
}
$('historyReload').onclick=refreshSharedHistory;
$('historyClearFilters').onclick=()=>{
 $('search').value='';$('filter').value='Todos';$('from').value='';$('to').value='';
 refreshSharedHistory();
};
function detail(r){$('detail').innerHTML=`<div class="card" style="margin-top:16px"><h3>Detalle ${esc(r.id)}</h3><p><b>Fecha:</b> ${esc(new Date(r.iso).toLocaleString('es-PE'))} · <b>Movimiento:</b> ${esc(r.tipo)} · <b>Placa:</b> ${esc(r.placa)}</p><p><b>Cliente:</b> ${esc(r.cliente)} · <b>Conductor:</b> ${esc(r.conductor)}</p><p><b>Configuración:</b> ${esc(r.configTransporte||'Unidad sola')} · <b>Carreta:</b> ${esc(r.carreta||'No aplica')} · <b>Cama baja:</b> ${esc(r.camaBaja||'No aplica')}</p><p><b>${r.maquinariaTransportada?'Maquinaria transportada':'Material'}:</b> ${esc(r.maquinariaTransportada||r.material)} · <b>Cantidad:</b> ${r.configTransporte==='Trabajo / servicio'?'No aplica':esc(r.cantidad)+' '+esc(r.unidad)} · <b>Guía:</b> ${esc(r.guia)}</p><p><b>Trabajo / motivo de salida:</b> ${esc(r.trabajo||'No especificado')}</p><p><b>Autorización:</b> ${esc(r.autorizacion)} · <b>Responsable:</b> ${esc(r.responsable)}</p><p><b>Observaciones:</b> ${esc(r.observaciones)}</p><div class="photo">${(r.fotos||[]).map(s=>`<a href="${s}" target="_blank"><img alt="Foto" src="${s}"></a>`).join('')}</div></div>`;}
for(let id of ['search','filter','from','to'])$(id).addEventListener('input',()=>AppMotion.task($('history'),renderHistory).catch(AppMotion.error));
function renderCatalog(){let k=$('catalogType').value,q=$('catalogSearch').value.toLocaleLowerCase('es');let a=catalogs[k].filter(v=>v.toLocaleLowerCase('es').includes(q));$('catalogList').innerHTML=`<p class="muted">${a.length} de ${catalogs[k].length} registros</p><table>${a.map(v=>`<tr><td>${esc(v)}</td></tr>`).join('')}</table>`}

$('catalogType').onchange=renderCatalog;$('catalogSearch').oninput=renderCatalog;$('catalogAdd').onclick=()=>{let v=$('catalogNew').value;if(!v.trim())return;addCatalog($('catalogType').value,v);$('catalogNew').value='';renderCatalog()};
$('backup').onclick=async()=>{let backup={version:3,exportedAt:new Date().toISOString(),catalogs,capacidades,records:await all(),localRecords:window.DibiserCloud?.connected()?await allLocal():undefined};download('DIBISER_respaldo_'+today()+'.json',new Blob([JSON.stringify(backup)],{type:'application/json'}))};$('restore').onclick=()=>$('restoreFile').click();$('restoreFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let d=JSON.parse(await f.text());if(!d.catalogs||!Array.isArray(d.records)||!['clientes','conductores','placas','materiales'].every(k=>Array.isArray(d.catalogs[k])))throw Error('Formato incorrecto');if(!confirm(`Importar ${d.records.length} registros? Los códigos existentes se actualizarán.`))return;for(let r of d.records){if(!r.id||!r.iso)throw Error('Registro inválido');await putLocal(r)}for(const k of Object.keys(INITIAL)){const previous=Array.isArray(catalogs[k])?catalogs[k]:[];const existing=Array.isArray(d.catalogs[k])?d.catalogs[k]:[];catalogs[k]=[...new Set([...previous,...existing,...INITIAL[k]])];}for(const k of ['placas','maquinarias'])catalogs[k]=catalogs[k].filter(v=>!remolquesExcluidos.has(String(v).trim().toLocaleUpperCase('es')));saveCats();if(d.capacidades&&typeof d.capacidades==='object'){for(const [p,entry] of Object.entries(d.capacidades))if(entry.cantidad>0)capacidades[p]=entry;guardarCapacidades();}renderCatalog();alert('Respaldo importado')}catch(err){alert('No se pudo importar: '+err.message)}e.target.value=''};
renderCatalog();


/* Panel de conexión central: sin activación automática ni pérdida de los datos locales. */
const cloud=window.DibiserCloud;
$('privateLinkActivate').onclick=async()=>{
 const button=$('privateLinkActivate');if(button.disabled)return;button.disabled=true;
 try{
  await cloud.activatePrivateLink($('privateLinkInput').value);
  $('privateLinkInput').value='';
  cloudStatusRender('Enlace validado. Consultando movimientos de todos los celulares...');
  await cloudRefresh();
  if(!$('history').classList.contains('hidden'))await refreshSharedHistory();
 }catch(e){cloudStatusRender('No se pudo conectar este celular: '+e.message);alert(e.message)}
 finally{button.disabled=false}
};
let recoveryActive=false,recoveryDone=false,recoveryFound=0;
const recoveryVerifiedIds=new Set();
async function checkLocalRecovery(){
 try{
  const local=await allLocal();
  recoveryFound=local.length;
  $('recoveryStatus').textContent=local.length?
   'Se encontraron '+local.length+' movimientos anteriores en este dispositivo. Se conservan y se mostrarán junto al historial central.':
   'No se encontraron movimientos en el almacenamiento de este navegador. Los de otra instalación o navegador pueden estar allí.';
  $('recoveryBackup').disabled=!local.length;
  $('recoveryView').disabled=!local.length;
  $('recoverySync').disabled=!local.length||!cloud.status().authorized;
  return local;
 }catch(e){
  $('recoveryStatus').textContent='No se pudo leer el historial de este navegador: '+e.message;
  $('recoveryBackup').disabled=true;$('recoveryView').disabled=true;$('recoverySync').disabled=true;
  return [];
 }
}
$('recoveryView').onclick=async()=>{
 const rows=await allLocal(),target=$('recoveryLocalList');
 target.classList.remove('hidden');
 if(!rows.length){target.textContent='En este navegador no aparecen movimientos locales. Comprueba la aplicación original donde fueron registrados.';return;}
 target.innerHTML='<p><strong>'+rows.length+' movimientos guardados en este dispositivo</strong></p><table><thead><tr><th>Fecha</th><th>Placa</th><th>Movimiento</th><th>Guía</th></tr></thead><tbody>'+rows.slice(0,200).map(r=>'<tr><td>'+esc(new Date(r.iso).toLocaleString('es-PE'))+'</td><td>'+esc(r.placa||'')+'</td><td>'+esc(r.tipo||'')+'</td><td>'+esc(r.guia||'')+'</td></tr>').join('')+'</tbody></table>'+(rows.length>200?'<p class="muted">Se muestran los 200 más recientes. El respaldo incluye todos.</p>':'');
};
$('recoveryBackup').onclick=async()=>{
 const local=await allLocal();
 if(!local.length)return alert('Este navegador no contiene movimientos locales. Abre la instalación donde registrabas los movimientos.');
 download('DIBISER_RECUPERACION_LOCAL_'+today()+'.json',new Blob([JSON.stringify({version:4,exportedAt:new Date().toISOString(),records:local,catalogs,capacidades})],{type:'application/json'}));
 AppMotion.notify('Respaldo local creado. Conserva el archivo JSON.');
};
async function recuperarHistorialAutomatico(){
 if(recoveryActive||!cloud.status().authorized)return;
 recoveryActive=true;
 let uploaded=0,duplicates=0,failures=0;
 try{
   const local=await checkLocalRecovery();
   if(!local.length){
     $('recoveryStatus').textContent='No se encontraron registros antiguos en este navegador. Usa «Recuperar desde respaldo JSON» si guardaste una copia, o abre el celular y la instalación originales.';
     recoveryDone=true;return;
   }
   const remote=await cloud.all(true),remoteById=new Map(remote.map(r=>[r.id,r]));
   const pending=local.filter(r=>r?.id&&r?.iso&&!remoteById.has(r.id));
   if(!pending.length){
     recoveryDone=true;
     $('recoveryStatus').textContent='Verificado: '+local.length+' registros locales, '+remote.length+' en nube. No hay registros pendientes de este celular.';
     return;
   }
   $('recoveryStatus').textContent='Encontrados '+pending.length+' registros antiguos pendientes. Se conservarán todos los originales.';
   for(const row of pending){
     try{
       const result=await cloud.save(row,null,true);
       if(result?.id!==row.id)throw Error('El servidor no confirmó el identificador '+row.id);
       uploaded++;recoveryVerifiedIds.add(row.id);
     }catch(error){
       failures++;
       $('recoveryStatus').textContent='Recuperación parcial: '+uploaded+' guardados y '+failures+' pendientes. Último error: '+error.message;
     }
   }
   // Leer de vuelta la base central: un envío no basta para afirmar que se recuperó.
   const after=await cloud.all(true);
   const afterIds=new Set(after.map(r=>r.id));
   const unverified=local.filter(r=>r?.id&&r?.iso&&!afterIds.has(r.id));
   recoveryDone=unverified.length===0;
   $('recoveryStatus').textContent=unverified.length===0
     ? 'Recuperación verificada: '+local.length+' registros de este celular presentes en la base central. Los originales siguen en el teléfono.'
     : 'Recuperación incompleta: '+(local.length-unverified.length)+' registros locales verificados en la nube; '+unverified.length+' pendientes. Conserva la aplicación y usa Recuperar y sincronizar ahora.';
   if(!unverified.length)AppMotion.notify('Historial anterior recuperado y verificado en la nube.');
   if(!$('history').classList.contains('hidden'))await refreshSharedHistory();
 }catch(error){
   recoveryDone=false;
   $('recoveryStatus').textContent='La recuperación no terminó: '+error.message+'. No se eliminaron registros. Reintenta cuando tengas conexión.';
 }finally{
   recoveryActive=false;
   $('recoverySync').disabled=!cloud.status().authorized;
 }
}
$('recoverySync').onclick=()=>recuperarHistorialAutomatico();
$('recoveryFileBtn').onclick=()=>$('recoveryFile').click();
$('recoveryFile').onchange=async event=>{
 const file=event.target.files[0];if(!file)return;
 try{
   const raw=JSON.parse(await file.text());
   // Respaldo habitual de DIBISER: records, y a veces localRecords.
   const candidates=[...(Array.isArray(raw.records)?raw.records:[]),...(Array.isArray(raw.localRecords)?raw.localRecords:[])];
   if(!candidates.length)throw Error('El archivo no contiene movimientos DIBISER en records/localRecords.');
   const originals=await allLocal(),existing=new Map(originals.map(row=>[row.id,row]));
   let added=0;
   for(const row of candidates){
     if(!row||typeof row.id!=='string'||typeof row.iso!=='string'||!row.id||!row.iso)continue;
     if(existing.has(row.id))continue; // Nunca sobreescribir un registro original del celular.
     await putLocal(row);
     existing.set(row.id,row);added++;
   }
   if(added===0&&existing.size===0)throw Error('No se encontraron movimientos válidos.');
   if(raw.catalogs&&typeof raw.catalogs==='object')for(const key of Object.keys(INITIAL)){
     if(Array.isArray(raw.catalogs[key]))catalogs[key]=[...new Set([...(catalogs[key]||[]),...raw.catalogs[key]])];
   }
   saveCats();
   await checkLocalRecovery();
   recoveryDone=false;
   $('recoveryStatus').textContent='Archivo revisado: '+candidates.length+' movimientos, '+added+' recuperados localmente sin sobrescribir registros. Verificando envío a la nube...';
   if(cloud.status().authorized)await recuperarHistorialAutomatico();
   if(!$('history').classList.contains('hidden'))await renderHistory();
   if(!cloud.status().authorized)alert('Se recuperaron '+added+' registros en este navegador. Abre el enlace privado para sincronizarlos.');
 }catch(error){alert('No se pudo recuperar el respaldo: '+error.message)}
 finally{event.target.value='';}
};

checkLocalRecovery();
function cloudStatusRender(message){
 const s=cloud.status();
 const label=s.linkMode?(s.authorized?'Enlace privado validado: todos los celulares autorizados comparten el mismo historial.':'Verificando acceso privado de DIBISER...')
  :'Acceso restringido. Solicita a DIBISER el enlace privado para ver y registrar movimientos.';
 $('cloudStatus').textContent=message||label;
 $('privateLinkActivation').classList.toggle('hidden',!!s.authorized);
 $('cloudConfigFields').classList.add('hidden');
 $('cloudAuthFields').classList.add('hidden');
 $('cloudHelp').classList.toggle('hidden',s.linkMode&&s.authorized);
 $('cloudHelp').textContent=s.linkMode?'Comparte únicamente el enlace privado de DIBISER. No publiques el enlace ni lo reenvíes a personas no autorizadas.':'Para entrar, abre el enlace privado que te envió DIBISER. No se necesita correo ni contraseña.';
 $('cloudImport').disabled=!s.authorized;
 $('recoverySync').disabled=!s.authorized||!recoveryFound||recoveryActive;
 $('cloudRefresh').disabled=!s.authorized;
 $('cloudLogout').disabled=!s.connected;
 $('cloudLogout').textContent=s.linkMode?'Quitar acceso de este celular':'Cerrar sesión';
 $('cloudImport').classList.toggle('hidden',!s.authorized);
 $('cloudRefresh').classList.toggle('hidden',!s.authorized);
 $('cloudLogout').classList.toggle('hidden',!s.authorized);
 document.body.classList.toggle('dibiser-access-ok',!!s.authorized);
}
async function cloudPullCatalogs(){
 if(!cloud.connected())return;
 const remote=await cloud.catalogItems();
 for(const item of remote.filter(x=>x.kind==='capacidadUnidad')){try{const e=JSON.parse(item.value);if(e.placa&&e.cantidad>0&&(!capacidades[e.placa]||String(e.updatedAt)>String(capacidades[e.placa].updatedAt))){capacidades[e.placa]={tipo:e.tipo,cantidad:e.cantidad,unidad:e.unidad,fuente:e.fuente,updatedAt:e.updatedAt};}}catch{}}
 guardarCapacidades();
 for(const item of remote.filter(x=>x.kind!=='capacidadUnidad')){if(Array.isArray(catalogs[item.kind])&&!catalogs[item.kind].includes(item.value)){catalogs[item.kind].push(item.value);}}
 saveCats();renderCatalog();
}
async function cloudRefresh(){
 if(!cloud.connected())return;
 if(!await cloud.member()){cloudStatusRender('El enlace privado no es válido o fue revocado. Solicita uno nuevo a DIBISER.');return;}
 await cloud.all(true);await cloudPullCatalogs();
 if(!recoveryDone)await recuperarHistorialAutomatico();
 if(!$('history').classList.contains('hidden'))await refreshSharedHistory();
 if(!$('report').classList.contains('hidden'))await renderReport();
 await mostrarGuiaAutomatica();
 cloudStatusRender();
}
$('cloudConfigure').onclick=()=>{try{cloud.setup($('cloudUrl').value,$('cloudKey').value);cloudStatusRender('Configuración guardada. Inicia sesión con un usuario autorizado.');}catch(err){alert(err.message)}};
$('cloudRegister').onclick=async()=>{
 const email=$('cloudEmail').value.trim(),password=$('cloudPassword').value;
 if(!email||password.length<8)return alert('Ingresa un correo válido y una contraseña de al menos 8 caracteres.');
 const b=$('cloudRegister');b.disabled=true;
 try{
   await cloud.signup(email,password);
   $('cloudPassword').value='';
   cloudStatusRender('Cuenta solicitada para '+email+'. Revisa tu correo para confirmar el registro. Un administrador de DIBISER deberá autorizarla antes de poder ver o enviar movimientos.');
   alert('Revisa tu correo para confirmar la cuenta. Luego solicita que DIBISER autorice tu usuario.');
 }catch(err){alert('No se pudo crear la cuenta: '+err.message)}
 finally{b.disabled=false;}
};
$('cloudLogin').onclick=async()=>{
 const b=$('cloudLogin');b.disabled=true;
 try{
  await cloud.login($('cloudEmail').value.trim(),$('cloudPassword').value);$('cloudPassword').value='';
  const member=await cloud.member();
  if(!member){
   cloudStatusRender('Cuenta iniciada, pero pendiente de autorización de DIBISER. No puedes ver ni guardar movimientos compartidos todavía.');
   return;
  }
  await cloudRefresh();cloudStatusRender('Conectado al historial central de DIBISER. Los nuevos registros se guardan en la nube.');
  const count=(await allLocal()).length;
  if(count)AppMotion.notify('Hay '+count+' registros guardados en este celular. Usa «Subir registros locales a la nube» para compartirlos.');
 }catch(err){alert('No se pudo conectar: '+err.message);cloudStatusRender()}
 finally{b.disabled=false}
};
$('cloudLogout').onclick=()=>{cloud.logout();cloudStatusRender();AppMotion.notify('Sesión central cerrada. Los registros remotos ya no están accesibles en este dispositivo.')};
$('cloudRefresh').onclick=()=>cloudRefresh().catch(err=>{cloudStatusRender('Error de conexión: '+err.message);alert(err.message)});
$('cloudImport').onclick=async()=>{
 const b=$('cloudImport'),rows=await allLocal();
 if(!cloud.connected())return alert('Inicia sesión en la nube.');
 if(!rows.length)return alert('Este celular no tiene movimientos anteriores para subir.');
 if(!confirm('Se subirán '+rows.length+' movimientos locales a la base compartida. Los registros originales del celular se conservarán. Realiza primero un respaldo JSON. ¿Continuar?'))return;
 b.disabled=true;
 try{
  // Respaldo obligatorio previo a cualquier migración.
  download('DIBISER_ANTES_DE_SINCRONIZAR_'+today()+'.json',new Blob([JSON.stringify({version:3,catalogs,capacidades,records:rows})],{type:'application/json'}));
  await cloud.importRows(rows,(done,total)=>{$('cloudStatus').textContent='Subiendo registros: '+done+' / '+total;});
  for(const [kind,values] of Object.entries(catalogs))for(const v of values)await cloud.saveCatalog(kind,v);
  await cloudRefresh();alert('Importación completada. El historial compartido ya incluye los registros de este celular.');
 }catch(err){alert('Importación interrumpida: '+err.message+'. Los datos locales se han conservado. Puedes repetir la importación.')}
 finally{b.disabled=false;cloudStatusRender()}
};
cloudStatusRender();
checkLocalRecovery();
if(cloud.connected())cloud.member().then(ok=>ok?cloudRefresh():cloudStatusRender('Enlace privado inválido o revocado.')).catch(e=>cloudStatusRender('No se pudo verificar el enlace privado: '+e.message));
setInterval(()=>{if(cloud.connected()&&!document.hidden)cloudRefresh().catch(e=>cloudStatusRender('Sin conexión central: '+e.message));},20000);
